<main id="main" class="inner-page shell"><div class="page-intro"><p class="eyebrow">YOUR ORDER HISTORY</p><h1>Your orders.</h1><p>Find your tracking number, check progress, and see your pickup details.</p></div><form class="shop-form shop-panel" method="get" action="<?= url('') ?>"><input type="hidden" name="route" value="order_tracking"><label for="find-order">Tracking number<input id="find-order" name="tracking" required maxlength="40" placeholder="WEB-..."></label><button class="button button-red" type="submit">Track your order ↗</button></form><div class="order-list"><?php foreach($orders as $order): ?><a class="shop-panel order-list-card" href="<?= url('?route=order_tracking&tracking='.rawurlencode($order['tracking_number'])) ?>"><div><p class="eyebrow"><?= $escape($order['tracking_number']) ?></p><h2><?= $escape($order['branch_name']) ?></h2><p class="muted"><?= $escape($order['created_at']) ?></p></div><div><span class="order-status"><?= $escape(ucfirst($order['status'])) ?></span><p class="order-list-total"><?= $escape($currency) ?><?= number_format($order['total'],2) ?></p><span class="text-link">View order ↗</span></div></a><?php endforeach; ?><?php if(!$orders): ?><div class="menu-empty"><h2>Your first order starts here.</h2><p>Your orders will appear here after checkout.</p><a class="button button-red" href="<?= url('?route=products') ?>">Explore the catalog ↗</a></div><?php endif; ?></div></main><?php require __DIR__.'/../partials/shop_close.php'; ?>
